        #region KungFu
        public static void StudyKungFu(Client.GameClient client, byte Star, byte Grade)
        {
            #region Send Study Packet
            byte[] Buf1 = new byte[19 + 8];
            Writer.WriteUInt16(19, 0, Buf1);//Packet Lenght
            Writer.WriteUInt16(2702, 2, Buf1);//Status Packet Id\
            uint TalentPiont = 0;
            TalentPiont = (uint)(client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentPoint - 10000);
            Writer.WriteUInt32(TalentPiont, 4, Buf1);//Talaint Point
            Writer.WriteUInt32(0, 6, Buf1);
            Writer.WriteByte(Star, 10, Buf1);//Star
            Writer.WriteByte(Grade, 11, Buf1);//Grade

            byte Types = 0;
            Types = (byte)Kernel.Random.Next(1, 16);
            byte Stright = 0;
            Stright = (byte)Kernel.Random.Next(1, 7);

            Writer.WriteByte(Types, 12, Buf1);//Type cric block ddf etc
            Writer.WriteByte(Stright, 13, Buf1);//Stright Like 300 6*50=300

            uint FreeTime = 0;
            FreeTime = (uint)(client.Entity.KunFuClasses.MainGui[client.Entity.UID].FreeTimes - 1);
            Writer.WriteByte((byte)1, 14, Buf1);//Free Time Usage
            client.Send(Buf1);
            #endregion
            switch (Grade)
            {
                #region Grade 1
                case 1://Grade 1 
                    {
                        switch (Star)//Stars In this Grade
                        {
                            case 1://Star 1
                                {
                                    #region Star 1
                                    if (!client.Entity.KunFuClasses.KungFuStages.ContainsKey(Grade))
                                    {
                                        #region CLient Doesn't exist
                                        Statement.KungFuGrades sub = new Statement.KungFuGrades();
                                        sub.UID = client.Entity.UID;
                                        sub.TotalOpened = 1;
                                        sub.Stage = Grade;
                                        sub.Kun1 = Types;
                                        sub.Str1 = Stright;
                                        uint kpkp = 0;
                                        kpkp = (uint)(Stright * 50);
                                        sub.Inner = kpkp;


                                        client.Entity.KunFuClasses.KungFuStages.Add(Grade, sub);
                                        Database.SubClassTable.InsertAttrbiuteKungFu(client.Entity.UID, 1, 1, kpkp, Types, Stright);
                                        #endregion
                                    }
                                    else
                                    {
                                        #region CLient Exist
                                        Statement.KungFuGrades sub = new Statement.KungFuGrades();
                                        sub.UID = client.Entity.UID;
                                        sub.TotalOpened = client.Entity.KunFuClasses.KungFuStages[Grade].TotalOpened;
                                        sub.Stage = Grade;
                                        sub.Kun1 = Types;
                                        sub.Str1 = Stright;

                                        //  sub.Kun1 = client.Entity.KunFuClasses.KungFuStages[Grade].Kun1;
                                        //  sub.Str1 = client.Entity.KunFuClasses.KungFuStages[Grade].Str1;
