            Writer.WriteUInt16(24, 0, Buf);//Packet Lenght
            Writer.WriteUInt16(2700, 2, Buf);//Status Packet Id
            Writer.WriteByte(13, 4, Buf);
            Writer.WriteByte(2, 5, Buf);//Client Id
            Writer.WriteByte((byte)TalentPiont.ToString().Length, 6, Buf);//Client Id
            string input = TalentPiont.ToString();
            char[] values = input.ToCharArray();

            int posx = 7;
            for (int x = 0; x < TalentPiont.ToString().Length; x++)
            {
                Writer.WriteByte((byte)values[x], posx, Buf);//Client Id
                posx += 1;

            }

            Writer.WriteByte(51, 15, Buf);//Client Id
            Writer.WriteByte(55, 16, Buf);//Client Id
            client.Send(Buf);
            #endregion
            client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentStatus = (byte)(client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentStatus - 1);
            client.Entity.KunFuClasses.MainGui[client.Entity.UID].FreeTimes = FreeTime;
            client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentPoint = TalentPiont;
            #region Update Main
            ///  
            uint Inners = 0;
            Inners = getInner2(client);
            Database.SubClassTable.UpdateKungFu(client.Entity, client.Entity.KunFuClasses.MainGui[client.Entity.UID].Name,
