             client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentPoint, client.Entity.KunFuClasses.MainGui[client.Entity.UID].FreeTimes
            , Inners);
            #endregion
            #region Packet 2700 with type 5
            byte[] Bufwss = new byte[23 + 8];
            Writer.WriteUInt16(23, 0, Bufwss);//Packet Lenght
            Writer.WriteUInt16(2700, 2, Bufwss);//Status Packet Id
            Writer.WriteByte(5, 4, Bufwss);
            Writer.WriteByte(2, 5, Bufwss);//Client Id
            Writer.WriteByte((byte)client.Entity.UID.ToString().Length, 6, Bufwss);//Client Id
            string inputs = client.Entity.UID.ToString();
            char[] valuess = inputs.ToCharArray();
            int poss = 7;
            for (int x = 0; x < client.Entity.UID.ToString().Length; x++)
            {
                Writer.WriteByte((byte)valuess[x], poss, Bufwss);//Client Id
                poss += 1;
            }
            Writer.WriteByte((byte)1, 14, Bufwss);//Client Id
            Writer.WriteByte((byte)(client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentStatus + 48), 15, Bufwss);//Client Id

            client.Send(Bufwss);
            client.Entity.TalentStaus = client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentStatus;
            Writer.WriteByte(client.Entity.TalentStaus, 241, client.Entity.SpawnPacket);
            client.SendScreen(client.Entity.SpawnPacket, false);
            #endregion
            #region UpDate Ranks
            Statement.KungFuRanks koko = new Statement.KungFuRanks();
            koko.UID = client.Entity.UID;
            koko.Level = client.Entity.Level;
            koko.KungName = client.Entity.KunFuClasses.MainGui[client.Entity.UID].Name;
            koko.Name = client.Entity.Name;
            koko.Intter = Inners;
            if (Conquer_Online_Server.Database.SubClassTable.KunFuRanks.ContainsKey(koko.UID))
            {
                Conquer_Online_Server.Database.SubClassTable.KunFuRanks.Remove(koko.UID);
                Conquer_Online_Server.Database.SubClassTable.KunFuRanks.Add(koko.UID, koko);
            }
            else
            {
                Conquer_Online_Server.Database.SubClassTable.KunFuRanks.Add(koko.UID, koko);
            }
            #endregion
        }
        public static uint getInner(uint Vale, GameClient client)
        {
            Statement.KungFuGrades siko = new Statement.KungFuGrades();
            siko = client.Entity.KunFuClasses.KungFuStages[Vale];

            switch (Vale)//Grades
            {
                #region Grade 1
                case 1:
                    {
                        Vale = (uint)((siko.Str1 * 50) + (siko.Str2 * 50) + (siko.Str3 * 50) + (siko.Str4 * 50) + (siko.Str5 * 50) + (siko.Str6 * 50) + (siko.Str7 * 50) + (siko.Str8 * 50) + (siko.Str9 * 50));
                        break;
                    }
                #endregion
                #region Grade 2
                case 2:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
                #region Grade 3
                case 3:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
                #region Grade 4
                case 4:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
                #region Grade 5
                case 5:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
                #region Grade 6
                case 6:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
                #region Grade 7
                case 7:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
                #region Grade 8
                case 8:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
                #region Grade 9
                case 9:
                    {
                        Vale = (uint)(siko.Str1 * 50 + siko.Str2 * 50 + siko.Str3 * 50 + siko.Str4 * 50 + siko.Str5 * 50 + siko.Str6 * 50 + siko.Str7 * 50 + siko.Str8 * 50 + siko.Str9 * 50);
                        break;
                    }
                #endregion
            }



            return (Vale);
        }
        public static uint getInner2(GameClient client)
        {
            Statement.KungFuGrades[] Classes = new Statement.KungFuGrades[client.Entity.KunFuClasses.KungFuStages.Count];
            client.Entity.KunFuClasses.KungFuStages.Values.CopyTo(Classes, 0);
            uint Vale = 0;
            foreach (Statement.KungFuGrades Class in Classes)
            {

                switch (Class.Stage)//Grades
                {
                    #region Grade 1
                    case 1:
                        {
                            Vale += (uint)((Class.Str1 * 50) + (Class.Str2 * 50) + (Class.Str3 * 50) + (Class.Str4 * 50) + (Class.Str5 * 50) + (Class.Str6 * 50) + (Class.Str7 * 50) + (Class.Str8 * 50) + (Class.Str9 * 50));
                            break;
                        }
                    #endregion
                    #region Grade 2
                    case 2:
                        {
                            Vale += (uint)(Class.Str1 * 50 + Class.Str2 * 50 + Class.Str3 * 50 + Class.Str4 * 50 + Class.Str5 * 50 + Class.Str6 * 50 + Class.Str7 * 50 + Class.Str8 * 50 + Class.Str9 * 50);
                            break;
                        }
                    #endregion
                    #region Grade 3
                    case 3:
                        {
                            Vale += (uint)(Class.Str1 * 50 + Class.Str2 * 50 + Class.Str3 * 50 + Class.Str4 * 50 + Class.Str5 * 50 + Class.Str6 * 50 + Class.Str7 * 50 + Class.Str8 * 50 + Class.Str9 * 50);
                            break;
                        }
                    #endregion
                    #region Grade 4
                    case 4:
                        {
                            Vale += (uint)(Class.Str1 * 50 + Class.Str2 * 50 + Class.Str3 * 50 + Class.Str4 * 50 + Class.Str5 * 50 + Class.Str6 * 50 + Class.Str7 * 50 + Class.Str8 * 50 + Class.Str9 * 50);
                            break;
                        }
                    #endregion
                    #region Grade 5
                    case 5:
                        {
                            Vale += (uint)(Class.Str1 * 50 + Class.Str2 * 50 + Class.Str3 * 50 + Class.Str4 * 50 + Class.Str5 * 50 + Class.Str6 * 50 + Class.Str7 * 50 + Class.Str8 * 50 + Class.Str9 * 50);
                            break;
                        }
                    #endregion
                    #region Grade 6
                    case 6:
                        {
                            Vale += (uint)(Class.Str1 * 50 + Class.Str2 * 50 + Class.Str3 * 50 + Class.Str4 * 50 + Class.Str5 * 50 + Class.Str6 * 50 + Class.Str7 * 50 + Class.Str8 * 50 + Class.Str9 * 50);
                            break;
                        }
                    #endregion
                    #region Grade 7
                    case 7:
                        {
                            Vale += (uint)(Class.Str1 * 50 + Class.Str2 * 50 + Class.Str3 * 50 + Class.Str4 * 50 + Class.Str5 * 50 + Class.Str6 * 50 + Class.Str7 * 50 + Class.Str8 * 50 + Class.Str9 * 50);
                            break;
                        }
                    #endregion
                    #region Grade 8
                    case 8:
                        {
                            Vale += (uint)(Class.Str1 * 50 + Class.Str2 * 50 + Class.Str3 * 50 + Class.Str4 * 50 + Class.Str5 * 50 + Class.Str6 * 50 + Class.Str7 * 50 + Class.Str8 * 50 + Class.Str9 * 50);
                            break;
                        }
