        public static ulong ClientSeal = BitConverter.ToUInt64(Encoding.Default.GetBytes("TQClient"), 0);
        public static void HandlePacket(byte[] packet, Client.GameClient client)
        {
            if (packet == null)
                return;
            if (client == null)
                return;
            ushort Length = BitConverter.ToUInt16(packet, 0);
            ushort ID = BitConverter.ToUInt16(packet, 2);

            if (client.Filtering)
                if (client.PacketFilter.Filter(ID))
                    return;

            if (ClientSeal != BitConverter.ToUInt64(packet, Length))
            {
                client.Disconnect();
                return;
            }
            switch (ID)
            {
                #region KungFu 2700
                case 2700:
                    {
                        byte TYPE = packet[4];
                        byte TYPE2 = packet[5];
                        byte Lenght = packet[6];
                        // string Namess = BitConverter.ToString(packet, 7);
                        uint unknowID = BitConverter.ToUInt32(packet, 7);
                        ConquerOnline.Network.KongFu.Main packe = new ConquerOnline.Network.KongFu.Main(false);
                        packe.Deserialize(packet);
                        switch (TYPE)
                        {

                            case 1://Add new Name 
                                {
                                    #region Add New KungFu
                                    string Names = System.Text.UTF8Encoding.Default.GetString(packet, 7, packet[6]);
                                    #region Add KongFu Name
                                    byte[] Buf1 = new byte[23 + 8];
                                    Writer.WriteUInt16(23, 0, Buf1);//Packet Lenght
                                    Writer.WriteUInt16(2700, 2, Buf1);//Status Packet Id
                                    Writer.WriteByte(TYPE, 4, Buf1);//type
                                    Writer.WriteByte(TYPE2, 5, Buf1);//Type
                                    Writer.WriteByte(Lenght, 6, Buf1);//Lenght of Name
                                    Writer.WriteString(Names, 7, Buf1);//Name  max 16 char
                                    client.Send(Buf1);
                                    #endregion
                                    if (!client.Entity.KunFuClasses.MainGui.ContainsKey(client.Entity.UID))
                                    {

                                        client.Entity.KunFuClasses.MainGui.Add(client.Entity.UID
                                              , new Conquer_Online_Server.Statement.KungFu()
                                              {
                                                  UID = client.Entity.UID,
                                                  Grade = 1,
                                                  TalentPoint = 50000,
                                                  FreeTimes = 10,
                                                  TalentStatus = 2,
                                                  Name = Names
                                              });
                                        Conquer_Online_Server.Database.SubClassTable.InsertKungFu(client.Entity,
                                            Names
                                       , 1, 2, 50000, 10);



                                        #region Packet 2700 with type 14
                                        byte[] Bufw = new byte[23 + 8];
                                        Writer.WriteUInt16(23, 0, Bufw);//Packet Lenght
                                        Writer.WriteUInt16(2700, 2, Bufw);//Status Packet Id
                                        Writer.WriteByte(14, 4, Bufw);
                                        Writer.WriteByte(3, 5, Bufw);//Client Id
                                        Writer.WriteByte((byte)client.Entity.UID.ToString().Length, 6, Bufw);//Client Id
                                        string input = client.Entity.UID.ToString();
                                        char[] values = input.ToCharArray();
                                        int posm = 7;
                                        for (int x = 0; x < client.Entity.UID.ToString().Length; x++)
                                        {
                                            Writer.WriteByte((byte)values[x], posm, Bufw);//Client Id
                                            posm += 1;
                                        }
                                        Writer.WriteByte(1, 14, Bufw);//Client Id
                                        Writer.WriteByte((byte)(client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentStatus + 48), 15, Bufw);//Client Id
                                        Writer.WriteByte(1, 16, Bufw);//Client Id
                                        Writer.WriteByte(49, 17, Bufw);//Client Id
                                        client.Send(Bufw);
                                        #endregion
                                        #region Packet 2701
                                        byte[] Buffers;
                                        Buffers = new byte[74];//18
                                        Writer.WriteUInt16(66, 0, Buffers);
                                        Writer.WriteUInt16(2701, 2, Buffers);//team pk
                                        Writer.WriteString(client.Entity.KunFuClasses.MainGui[client.Entity.UID].Name, 4, Buffers); //1
                                        Writer.WriteByte(client.Entity.KunFuClasses.MainGui[client.Entity.UID].Grade, 20, Buffers); //Grade
                                        Writer.WriteByte(client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentStatus, 21, Buffers);//talent Staus
                                        Writer.WriteByte(0, 22, Buffers);//team pk
                                        Writer.WriteUInt32(client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentPoint, 23, Buffers);//talentPoint  100000= 1 chance
                                        Writer.WriteByte(215, 27, Buffers);//Type For Stage 1
                                        Writer.WriteByte(0, 28, Buffers);//6X50=300
                                        Writer.WriteUInt32(client.Entity.KunFuClasses.MainGui[client.Entity.UID].FreeTimes, 35, Buffers);//team pk
                                        Writer.WriteUInt32(9999999, 39, Buffers);//team pk
                                        Writer.WriteUInt32(0, 43, Buffers);//Free Tims Used Today
                                        client.Send(Buffers);
                                        #endregion
                                        #region Packet 2700 with type 5
                                        byte[] Bufwss = new byte[23 + 8];
                                        Writer.WriteUInt16(23, 0, Bufwss);//Packet Lenght
                                        Writer.WriteUInt16(2700, 2, Bufwss);//Status Packet Id
                                        Writer.WriteByte(5, 4, Bufwss);
                                        Writer.WriteByte(2, 5, Bufwss);//Client Id
                                        Writer.WriteByte((byte)client.Entity.UID.ToString().Length, 6, Bufwss);//Client Id
                                        string inputs = client.Entity.UID.ToString();
                                        char[] valuess = inputs.ToCharArray();
                                        int poss = 7;
                                        for (int x = 0; x < client.Entity.UID.ToString().Length; x++)
                                        {
                                            Writer.WriteByte((byte)valuess[x], poss, Bufwss);//Client Id
                                            poss += 1;
                                        }
                                        Writer.WriteByte(1, 14, Bufwss);//Client Id
                                        Writer.WriteByte((byte)(client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentStatus + 48), 15, Bufwss);//Client Id
                                        client.Send(Bufwss);
                                        #endregion
                                        #region Packet 2700 with type 13
                                        byte[] Bufwss1 = new byte[23 + 8];
                                        Writer.WriteUInt16(23, 0, Bufwss1);//Packet Lenght
                                        Writer.WriteUInt16(2700, 2, Bufwss1);//Status Packet Id
                                        Writer.WriteByte(13, 4, Bufwss1);
                                        Writer.WriteByte(2, 5, Bufwss1);//Client Id
                                        Writer.WriteByte((byte)client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentPoint.ToString().Length, 6, Bufwss1);//Client Id
                                        string inputss = client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentPoint.ToString();
                                        char[] valuesss = inputss.ToCharArray();
                                        int posss = 7;
                                        for (int x = 0; x < client.Entity.KunFuClasses.MainGui[client.Entity.UID].TalentPoint.ToString().Length; x++)
                                        {
                                            Writer.WriteByte((byte)valuesss[x], posss, Bufwss1);//Client Id
                                            posss += 1;
                                        }

                                        //  Writer.WriteByte(10, 12, Bufwss1);//Client Id
                                        // Writer.WriteByte(49, 13, Bufwss1);//Client Id

                                        Writer.WriteByte(53, 14, Bufwss1);//Client Id
                                        Writer.WriteByte(55, 15, Bufwss1);//Client Id


                                        ///////
                                        Writer.WriteByte(51, 16, Bufwss1);//Client Id
                                        Writer.WriteByte(55, 17, Bufwss1);//Client Id
                                        Writer.WriteByte(53, 18, Bufwss1);//Client Id
                                        Writer.WriteByte(54, 19, Bufwss1);//Client Id
                                        Writer.WriteByte(55, 20, Bufwss1);//Client Id
                                        Writer.WriteByte(56, 21, Bufwss1);//Client Id
                                        Writer.WriteByte(56, 22, Bufwss1);//Client Id
                                        client.Send(Bufwss1);
                                        #endregion
                                    }
                                    #endregion

                                    break;
                                }
                            case 9:// See PLayers
                                {
                                    #region Check Players  not complete
                                    uint vOut = Convert.ToUInt32(packe.Text);
                                    if (vOut == 0)
                                        return;
                                    if (!Kernel.GamePool.ContainsKey(vOut))
                                    {
                                        return;
                                    }
                                    if (Kernel.GamePool[vOut].Entity == null)
                                        return;
                                    if (Kernel.GamePool[vOut].Entity.KunFuClasses.MainGui.Count > 0)
                                    {
                                        byte[] Buffers;
                                        Buffers
                = new byte[508];//18
                                        Writer.WriteUInt16(500, 0, Buffers);
                                        Writer.WriteUInt16(2701, 2, Buffers);//team pk
                                        Writer.WriteString(Kernel.GamePool[vOut].Entity.KunFuClasses.MainGui[vOut].Name, 4, Buffers); //1
                                        Writer.WriteByte(Kernel.GamePool[vOut].Entity.KunFuClasses.MainGui[vOut].Grade, 20, Buffers); //Grade
                                        Writer.WriteByte(Kernel.GamePool[vOut].Entity.KunFuClasses.MainGui[vOut].TalentStatus, 21, Buffers);//talent Staus
                                        Writer.WriteByte(1, 22, Buffers);//team pk
                                        Writer.WriteUInt32(Kernel.GamePool[vOut].Entity.KunFuClasses.MainGui[vOut].TalentPoint, 23, Buffers);//talentPoint
                                        Writer.WriteByte(9, 27, Buffers);//Type For Stage 1
                                        Writer.WriteByte(6, 28, Buffers);//6X50=300
                                        Writer.WriteUInt32(Kernel.GamePool[vOut].Entity.KunFuClasses.MainGui[vOut].FreeTimes, 35, Buffers);//team pk
                                        Writer.WriteUInt32(9999999, 39, Buffers);//team pk
                                        Writer.WriteUInt32(0, 43, Buffers);//Free Tims Used Today
                                        int pos = 48;

                                        if (Kernel.GamePool[vOut].Entity.KunFuClasses.KungFuStages.Count > 0)
                                        {
                                            Statement.KungFuGrades[] Classes = new Statement.KungFuGrades[Kernel.GamePool[vOut].Entity.KunFuClasses.KungFuStages.Count];
                                            Kernel.GamePool[vOut].Entity.KunFuClasses.KungFuStages.Values.CopyTo(Classes, 0);
                                            foreach (Statement.KungFuGrades Class in Classes)
                                            {
                                                Writer.WriteByte((byte)Class.Kun1, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str1, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun2, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str2, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun3, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str3, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun4, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str4, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun5, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str5, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun6, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str6, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun7, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str7, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun8, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str8, pos, Buffers);//6X50=300
                                                pos += 1;

                                                Writer.WriteByte((byte)Class.Kun9, pos, Buffers);//Type For Stage 1
                                                pos += 1;
                                                Writer.WriteByte(Class.Str9, pos, Buffers);//6X50=300
                                                pos += 1;
                                            }
                                        }
                                        client.Send(Buffers);
                                    }
                                    else
                                    {
                                        client.Send(new NpcReply(NpcReply.MessageBox, "Este jogador ainda não entrou no sistema JiangHu."));
                                        return;
                                    }
                                    #endregion
                                    break;
                                }

                            case 13:
                                {
                                    #region Packet 2700 with type 13
                                    byte[] Bufwss1 = new byte[23 + 8];
                                    Writer.WriteUInt16(23, 0, Bufwss1);//Packet Lenght
                                    Writer.WriteUInt16(2700, 2, Bufwss1);//Status Packet Id
                                    Writer.WriteByte(13, 4, Bufwss1);
