                case 2703:// See PLayers
                    {
                        #region Check Players  not complete
                        //  uint vOut = Convert.ToUInt32(packe.Text);
                        ushort pages = BitConverter.ToUInt16(packet, 4);
                        //if (client.Entity.KunFuClasses.MainGui.Count >0)
                        //{
                        ushort Position = 24;
                        uint charamount = 0;
                        uint place = 1;
                        uint chiu = 0;

                        int pos = 8;
                        int popo = 1;
                        Conquer_Online_Server.Database.SubClassTable.Rankss = Conquer_Online_Server.Database.SubClassTable.KunFuRanks.Values.OrderByDescending((c) => c.Intter).ToArray();
                        // Conquer_Online_Server.Database.SubClassTable.CHiRankss = Conquer_Online_Server.Database.SubClassTable.ChiRanks.Values.OrderByDescending((c) => c.Score).ToArray();
                        byte[] Buffers;
                        Buffers
= new byte[908];//18
                        Writer.WriteUInt16(900, 0, Buffers);
                        Writer.WriteUInt16(2703, 2, Buffers);//team pk
                        Writer.WriteUInt16(pages, 4, Buffers);//Page
                        Writer.WriteByte(10, 6, Buffers);//10 in Page
                        Writer.WriteByte((byte)(Conquer_Online_Server.Database.SubClassTable.Rankss.Length), 7, Buffers);//100 PLayer
                        pages = (ushort)(pages - 1);
                        if (Conquer_Online_Server.Database.SubClassTable.Rankss.Length < pages * 10)
                            return;
                        int rank = (int)pages * 10;
                        uint counts = (uint)Math.Min(Conquer_Online_Server.Database.SubClassTable.Rankss.Length - pages * 10, 10);

                        for (int x = rank; x < rank + counts; x++)
                        {
                            var current = Conquer_Online_Server.Database.SubClassTable.Rankss[x];
                            if (current.Intter == 0)
                            {
                                continue;
                            }
                            Writer.WriteByte((byte)(x + 1), pos, Buffers);//Postion
                            popo += 1;
                            pos += 1;
                            Writer.WriteUInt32(current.Intter, pos, Buffers);
                            pos += 4;
                            Writer.WriteUInt32(current.Level, pos, Buffers);
                            pos += 4;
                            Writer.WriteString(current.Name, pos, Buffers);
                            pos += 16;
                            Writer.WriteString(current.KungName, pos, Buffers);
                            pos += 16;
                        }
                        client.Send(Buffers);
                        // }
                        #endregion
                        break;
                    }
