                                    if (wh == null) return;
                                    ConquerItem item = null;
                                    if (client.Inventory.TryGetItem(warehousepacket.UID, out item))
                                    {
                                        if (item.ID >= 729960 && item.ID <= 729970)
                                            return;
                                        if (item.ID == 729611 || item.ID == 729612 || item.ID == 729613 || item.ID == 729614 || item.ID == 729703)
                                            return;
