                case 2072:
                    {
                        RacePotion pot = new RacePotion(false);
                        pot.Deserialize(packet);
                        int i = pot.Location - 1;
                        if (i < 0 || i > 4)
                            return;
                        if (client.Potions[i] == null)
                            return;
                        var potion = client.Potions[i];
                        potion.Count--;

                        pot.PotionType = potion.Type;
                        pot.Amount = (ushort)potion.Count;
